def is_good_triple(x, y, z):
    """
    Checks if (x, y, z) is a good triple, meaning (x+1)^y / (x^z + 1) is an integer.
    """
    numerator = (x + 1)**y
    denominator = x**z + 1

    if denominator == 0:
        # Should not happen since x >= 1 and z >= 1
        return False

    return numerator % denominator == 0

