def is_good_triple(x, y, z):
    """Checks if (x, y, z) is a good triple."""
    if x <= 0 or y <= 0 or z <= 0:
        return False

    # The condition is (x^z + 1) divides (x+1)^y
    divisor = x**z + 1
    dividend = (x + 1)**y

    # Check for divisibility
    return dividend % divisor == 0

def count_good_triples(limit):
    count = 0
    for x in range(1, limit + 1):
        for y in range(1, limit + 1):
            for z in range(1, limit + 1):
                if is_good_triple(x, y, z):
                    count += 1
    return count

