def is_good_triple(x, y, z):
    # Check if (x^z + 1) divides (x+1)^y

    # x, y, z are positive integers < 100.

    # Calculate numerator and denominator
    # Using pow(base, exp) is generally safer/faster for exponentiation

    # Numerator: (x+1)^y
    try:
        numerator = pow(x + 1, y)
    except OverflowError:
        # Should not happen for 99^99 in standard Python integers, 
        # but good practice if language constraints were different.
        return False 

    # Denominator: x^z + 1
    denominator = pow(x, z) + 1

    # Check for divisibility
    if denominator == 0: # Should not happen since x >= 1, z >= 1
        return False

    if numerator % denominator == 0:
        return True
    return False

